import React from 'react';
import { Link, NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';

export default function Navbar() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const navLinkClass = ({ isActive }) =>
    isActive
      ? 'text-[#1d64f2] font-bold transition'
      : 'text-gray-600 hover:text-[#1d64f2] font-medium transition';

  return (
    <header className="bg-white text-slate-900 border-b border-gray-100 sticky top-0 z-50">
      <div className="max-w-6xl mx-auto px-6 py-4 flex justify-between items-center">
        {/* โลโก้ CarRent */}
        <Link to="/" className="inline-flex items-baseline font-extrabold text-2xl tracking-tight">
  <span className="text-[#1d64f2]">Car</span>
  <span className="text-slate-900">Rent</span>
  <span className="inline-block w-2 h-2 rounded-full bg-[#f59e0b] ml-0.5"></span>
</Link>

        {/* เมนูหลัก: หน้าแรก, รถของเรา, API Lab, เกี่ยวกับ */}
        <nav className="hidden md:flex items-center space-x-7 text-sm">
          <NavLink to="/" end className={navLinkClass}>หน้าแรก</NavLink>
          <NavLink to="/cars" className={navLinkClass}>รถของเรา</NavLink>
          <NavLink to="/api-lab" className={navLinkClass}>API Lab</NavLink>
          <NavLink to="/about" className={navLinkClass}>เกี่ยวกับ</NavLink>

          {user && (
            <>
              <NavLink to="/my-bookings" className={navLinkClass}>การจองของฉัน</NavLink>
              <NavLink to="/profile" className={navLinkClass}>โปรไฟล์</NavLink>
            </>
          )}
          {user?.role === 'admin' && (
            <Link
              to="/admin"
              className="bg-blue-50 text-[#1d64f2] border border-blue-200 px-3 py-1 rounded-lg font-bold text-xs"
            >
              Admin Panel
            </Link>
          )}
        </nav>

        {/* ปุ่ม Login / Register / Logout */}
        <div className="flex items-center space-x-4 text-sm font-medium">
          {user ? (
            <>
              <span className="text-gray-600 hidden sm:inline">สวัสดี, {user.full_name}</span>
              <button
                onClick={handleLogout}
                className="border border-gray-300 text-gray-700 px-4 py-1.5 rounded-lg hover:bg-gray-50 transition"
              >
                ออกจากระบบ
              </button>
            </>
          ) : (
            <>
              <Link to="/login" className="text-gray-600 hover:text-[#1d64f2] transition">เข้าสู่ระบบ</Link>
              <Link
                to="/register"
                className="bg-[#1d64f2] text-white font-semibold px-4 py-2 rounded-lg hover:bg-blue-700 transition shadow-sm"
              >
                สมัครสมาชิก
              </Link>
            </>
          )}
        </div>
      </div>
    </header>
  );
}
